+
+/*
+ * Make sure `va` is backed by a physical frame in `pgdir` (a pa) and return
+ * the kernel virtual address of that frame.  A page that had been swapped out
+ * is read back from the SD card first.  The signature matches the callback
+ * load_elf() expects, so it doubles as the "prepare page" hook of do_exec().
+ */
+uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
+{
+    va = ROUNDDOWN(va, PAGE_SIZE);
+    PTE *pte = walk_pgdir(va, pgdir);
+
+    if(!get_attribute(*pte, _PAGE_PRESENT)){
+        if(get_attribute(*pte, _PAGE_SOFT)){
+            /* the page lives in the swap area, fetch it back */
+            uint64_t slot = get_pfn(*pte);
+            uintptr_t pa = alloc_user_page(0, pte);
+            sbi_sd_read((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + slot * PAGE_SD_BLOCKS);
+            disk_page[slot].valid = 0;
+            *pte = 0;
+            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
+        }
+        else{
+            uintptr_t pa = alloc_user_page(0, pte);
+            *pte = 0;
+            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
+        }
+        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE | _PAGE_EXEC |
+                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
+        flush_tlb_all();
+    }
+
+    return pa2kva(get_pa(*pte));
+}
