    printk("[plic] plic:    0x%x\n\r", plic_addr);
    printk("[plic] nr_irqs: 0x%x\n\r", nr_irqs);

    XPS_SYS_CTRL_BASEADDR = (uintptr_t)ioremap((uint64_t)slcr_bade_addr, NORMAL_PAGE_SIZE);
    xemacps_config.BaseAddress = (uintptr_t)ioremap((uint64_t)ethernet_addr, NORMAL_PAGE_SIZE);
    xemacps_config.DeviceId        = 0;
    xemacps_config.IsCacheCoherent = 0;
    printk("[slcr_bade_addr] phy:%x virt:%lx\n\r", slcr_bade_addr, XPS_SYS_CTRL_BASEADDR);
    printk("[ethernet_addr]  phy:%x virt:%lx\n\r", ethernet_addr, xemacps_config.BaseAddress);

    uintptr_t _plic_addr = (uintptr_t)ioremap((uint64_t)plic_addr, 0x4000 * NORMAL_PAGE_SIZE);
    printk("[plic_addr]      phy:%x virt:%lx\n\r", plic_addr, _plic_addr);
    plic_init(_plic_addr, nr_irqs);

    long status = EmacPsInit(&EmacPsInstance);
    if (status != XST_SUCCESS) {
        printk("> [INIT] Error: Ethernet Driver Initialization Failed!\n\r");
        assert(0);
    }
    else{
        printk("> [INIT] Ethernet Driver Initialization Succeeded.\n\r");
    }

    // read CPU frequency and calc timer interval
    time_base = sbi_read_fdt(TIMEBASE);
    timer_interval = (uint64_t)(time_base / 100);
    printk("> [INIT] Set Timer Interval Successfully.\n\r");

    // init Process Control Block
    init_pcb();
    printk("> [INIT] PCB Initialization Succeeded.\n\r");

    // init futex mechanism and binsem mechanism
    init_system_futex();
    init_system_binsem();

    // init interrupt
    init_exception();
    printk("> [INIT] Interrupt Processing Initialization Succeeded.\n\r");

    // init system call table
    init_syscall();
    printk("> [INIT] System Call Initialized Successfully.\n\r");

    // init screen
    init_screen();
    printk("> [INIT] Screen Initialization Succeeded.\n\r");

    // wakeup another core
    spin_lock_init(&kernel_lock);
    wakeup_other_hart();
    while(!smp_init_flag){
        ;
    }
    printk("> [INIT] Start the Second Core Successfully.\n\r"); 

    // Setup timer interrupt and enable all interrupt
    enable_interrupt();
    setup_exception();
    sbi_set_timer(get_ticks() + timer_interval);

    while (1){
        disable_preempt();
        list_node_t* clean_node = kernel_pcb[0].wait_list.next;
        while(clean_node != &kernel_pcb[0].wait_list){
            pcb_t *clean_pcb = list_entry(clean_node, pcb_t, list);
            // release pcb
            clean_pcb->status = TASK_EXITED;
            clean_pcb->pid = -1;
            // release kernel stack
            free_user_page(kva2pa(clean_pcb->kernel_stack_base - PAGE_SIZE));

            clean_node = clean_node->next;
            list_del(clean_node->prev);
        }

        enable_preempt();
        __asm__ __volatile__("wfi\n\r":::);
    }
}

