258	/* Give up every binary semaphore `task` still holds and hand each of them to
259	 * the next waiter, so that nobody stays blocked on a dead process. */
260	static void release_binsem(pcb_t *task)
261	{
262	    while (task->binsem_num > 0) {
263	        int id = task->binsem_id[--task->binsem_num];
264	        binsem_node_t *node = &binsem_nodes[id];
265	
266	        node->sem++;
267	        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
268	            list_node_t *heir_node = node->block_queue.next;
269	            pcb_t *heir = list_entry(heir_node, pcb_t, list);
270	            heir->binsem_id[heir->binsem_num++] = id;
271	            do_unblock(heir_node);
272	        }
273	    }
274	}
