 38	/*
 39	 * A brand new address space costs a few frames right away (the ELF image, the
 40	 * first stack page and the kernel stack).  Refuse to exec instead of running
 41	 * into an allocation that cannot be satisfied even by swapping.
 42	 */
 43	#define EXEC_MIN_FREE_PAGES 16
 44	
 45	static void destroy_task(pcb_t *task, int still_on_kernel_stack);
 46	
 47	/*
 48	 * A task cannot be destroyed while it is running: its page table is installed
 49	 * in `satp` and it is standing on its own kernel stack.  do_kill() and
 50	 * do_exit() therefore only mark the victim here, and the hart it runs on
 51	 * finishes the job on its way out of scheduler().  The mark lives outside the
 52	 * pcb because `status` is overwritten by every do_block().
 53	 */
 54	static pcb_t * volatile pending_kill[NR_CPUS];
 55	
 56	/*
 57	 * A task released with AUTO_CLEANUP_ON_EXIT is handed to the idle task of
 58	 * core 0, which frees its kernel stack -- the very stack the dying task is
 59	 * still standing on while it unwinds out of the kernel.  Publishing it one
 60	 * scheduling round later gives it all the time it needs to leave.
 61	 */
 62	static pcb_t * volatile pending_reap[NR_CPUS];
 63	
 64	/*
 65	 * Only modify PCB, current_running, process_id and ready_queue
 66	 * DO NOT STORE OR RESTORE
 67	 * trick: modify $tp in ret_from_exception to ensure
 68	 * disable_preempt() and enable_preempt() modify the same PCB
 69	 */
 70	void scheduler(void)
 71	{
 72	    pcb_t *prev = current_running[cpu_id];
 73	    pcb_t *next;
 74	    pcb_t *dying = NULL;
 75	    list_node_t *next_node;
 76	
 77	    /* the task torn down one round ago has left its kernel stack by now */
 78	    if (pending_reap[cpu_id] != NULL) {
 79	        list_add_tail(&pending_reap[cpu_id]->list, &kernel_pcb[0].wait_list);
 80	        pending_reap[cpu_id] = NULL;
 81	    }
 82	
 83	    if (prev != &kernel_pcb[cpu_id]) {
 84	        if (pending_kill[cpu_id] == prev) {
 85	            pending_kill[cpu_id] = NULL;
 86	            dying = prev;
 87	        } else if (prev->status == TASK_RUNNING) {
 88	            /* still runnable: back to the tail of the ready queue */
 89	            prev->status = TASK_READY;
 90	            prev->ready_tick = get_ticks();
 91	            list_add_tail(&prev->list, &ready_queue);
 92	        }
 93	    }
 94	
 95	    next_node = max_priority_node();
 96	    if (next_node == NULL) {
 97	        /* nothing this hart may run, go back to its idle task */
 98	        next = &kernel_pcb[cpu_id];
 99	    } else {
100	        list_del(next_node);
101	        next = list_entry(next_node, pcb_t, list);
102	    }
103	
104	    next->status = TASK_RUNNING;
105	    next->cpu_id = cpu_id;
106	    current_running[cpu_id] = next;
107	    /* ret_from_exception restores the context of `current_cpu_running` */
108	    current_cpu_running = next;
109	
110	    /* every task owns its own cursor position */
111	    screen_cursor_x[cpu_id] = next->cursor_x;
112	    screen_cursor_y[cpu_id] = next->cursor_y;
113	
114	    /* install the address space of the new task; the kernel window is part
115	     * of every page table, so the code below keeps running just fine */
116	    set_satp(SATP_MODE_SV39, 0, ((uintptr_t)next->pgdir) >> NORMAL_PAGE_SHIFT);
117	    local_flush_tlb_all();
118	
119	    /* now that we no longer run inside it, the old address space may go */
120	    if (dying != NULL) {
121	        destroy_task(dying, 1);
122	    }
123	}
