125	/*
126	 * Prepare the kernel stack of a brand new process so that ret_from_exception
127	 * drops it into `entry_point` in user mode with argc/argv in a0/a1.
128	 */
129	static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point,
130	                           pcb_t *new_pcb, int argc, uintptr_t argv)
131	{
132	    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
133	    new_pcb->kernel_sp = kernel_stack - sizeof(regs_context_t);
134	
135	    /* the pcb slot may have been used before, do not inherit stale registers */
136	    memset(pt_regs, 0, sizeof(regs_context_t));
137	
138	    /* initialization registers: ra, sp, gp, a0, a1, sstatus, sepc, sscratch */
139	    pt_regs->regs[1] = (reg_t)entry_point;       //ra
140	    pt_regs->regs[2] = (reg_t)user_stack;        //sp
141	    pt_regs->regs[3] = (reg_t)__global_pointer$; //gp
142	    pt_regs->regs[10] = (reg_t)argc;             //a0, argc of main()
143	    pt_regs->regs[11] = (reg_t)argv;             //a1, argv of main()
144	    pt_regs->sepc = (reg_t)entry_point;          //sepc
145	    pt_regs->sstatus = (reg_t)SR_SPIE;           //SPP = 0, SPIE = 1
146	    pt_regs->sscratch = (reg_t)new_pcb;          //sscratch = tp
147	}
