149	/*
150	 * Copy the arguments of the caller onto the freshly created user stack of
151	 * `new_pcb` and return the user virtual address of the argv array.  The page
152	 * is filled in through the kernel's direct mapping, which is reachable no
153	 * matter which address space is currently installed.  `*argc_io` is updated
154	 * to the number of arguments that actually fit, so that the a0 handed to the
155	 * new process can never disagree with the array a1 points at.
156	 */
157	static uintptr_t init_user_stack(pcb_t *new_pcb, int *argc_io, char *argv[])
158	{
159	    uintptr_t top_va = USER_STACK_ADDR;
160	    uintptr_t top_kva = alloc_page_helper(top_va - PAGE_SIZE,
161	                                          (uintptr_t)new_pcb->pgdir) + PAGE_SIZE;
162	    /* the last `top_va - va` bytes of the page hold the address `va` */
163	    #define STACK_KVA(va) (top_kva - (top_va - (uintptr_t)(va)))
164	
165	    int argc = *argc_io;
166	    int len[MAX_EXEC_ARGC];
167	    uintptr_t string_va[MAX_EXEC_ARGC];
168	    uintptr_t sp = top_va;
169	    int i;
170	
171	    /* Everything written here has to stay inside this single page, because
172	     * only this page is reachable through `top_kva`.  Measure first and drop
173	     * arguments from the tail until the strings, the argv array, the
174	     * alignment slack and a little room for the callee all fit. */
175	    uintptr_t budget = PAGE_SIZE - 64;
176	    uintptr_t need = 0;
177	    for (i = 0; i < argc; i++) {
178	        len[i] = strlen(argv[i]) + 1;
179	        need += (uintptr_t)len[i];
180	    }
181	    while (argc > 0 &&
182	           need + sizeof(uintptr_t) * (argc + 2) > budget) {
183	        need -= (uintptr_t)len[--argc];
184	    }
185	
186	    /* the strings themselves, topmost first */
187	    for (i = argc - 1; i >= 0; i--) {
188	        sp -= (uintptr_t)len[i];
189	        memcpy((uint8_t *)STACK_KVA(sp), (const uint8_t *)argv[i], (uint32_t)len[i]);
190	        string_va[i] = sp;
191	    }
192	
193	    /* then the NULL terminated array pointing at them */
194	    sp = ROUNDDOWN(sp, sizeof(uintptr_t));
195	    sp -= (argc + 1) * sizeof(uintptr_t);
196	    uintptr_t *slot = (uintptr_t *)STACK_KVA(sp);
197	    for (i = 0; i < argc; i++) {
198	        slot[i] = string_va[i];
199	    }
200	    slot[argc] = 0;
201	
202	    uintptr_t argv_va = sp;
203	    /* the RISC-V ABI wants a 16 byte aligned stack pointer */
204	    new_pcb->user_sp = ROUNDDOWN(sp, 16);
205	    *argc_io = argc;
206	
207	    #undef STACK_KVA
208	    return argv_va;
209	}
