211	/*
212	 * Load the ELF image called `file_name` into a brand new address space and
213	 * make it a runnable process.  The return value is the one the shell expects:
214	 * -1 when there is no such program, 0 when the process table is full, -2 when
215	 * memory ran out and the new pid on success.
216	 */
217	pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
218	{
219	    disable_preempt();
220	    /* file_name and argv live in the caller's user space */
221	    enable_sum();
222	
223	    unsigned char *binary = NULL;
224	    int length = 0;
225	    if (file_name == NULL || !get_elf_file(file_name, &binary, &length)) {
226	        disable_sum();
227	        enable_preempt();
228	        return -1;
229	    }
230	
231	    /* clamp once, so that the array built on the user stack and the `argc`
232	     * handed to main() can never disagree */
233	    if (argc < 0 || argv == NULL) {
234	        argc = 0;
235	    }
236	    if (argc > MAX_EXEC_ARGC) {
237	        argc = MAX_EXEC_ARGC;
238	    }
239	
240	    /* look for a free pcb: `pid == -1` marks an unused slot */
241	    int i;
242	    for (i = 0; i < NUM_MAX_TASK; i++) {
243	        if (pcb[i].pid == -1) {
244	            break;
245	        }
246	    }
247	    if (i == NUM_MAX_TASK) {
248	        disable_sum();
249	        enable_preempt();
250	        return 0;
251	    }
252	
253	    if (free_page_num() < EXEC_MIN_FREE_PAGES) {
254	        disable_sum();
255	        enable_preempt();
256	        return -2;
257	    }
258	
259	    pcb_t *new_pcb = &pcb[i];
260	    new_pcb->pgdir = init_page_table();
261	    /* the kernel stack is a pinned physical page used through the direct map */
262	    new_pcb->kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
263	    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
264	    new_pcb->user_sp = USER_STACK_ADDR;
265	    new_pcb->user_stack_base = USER_STACK_ADDR;
266	    new_pcb->preempt_count = 0;
267	    init_list_head(&new_pcb->wait_list);
268	    init_list_head(&new_pcb->timer.list);
269	    new_pcb->binsem_num = 0;
270	    new_pcb->pid = process_id++;
271	    new_pcb->type = USER_PROCESS;
272	    new_pcb->status = TASK_READY;
273	    new_pcb->mode = mode;
274	    new_pcb->priority = 1;
275	    new_pcb->ready_tick = get_ticks();
276	    /* a child may run wherever its parent was allowed to run */
277	    new_pcb->mask = current_running[cpu_id]->mask;
278	    if (new_pcb->mask == 0) {
279	        new_pcb->mask = (1UL << NR_CPUS) - 1;
280	    }
281	    new_pcb->cpu_id = cpu_id;
282	    new_pcb->cursor_x = 1;
283	    new_pcb->cursor_y = 1;
284	
285	    uintptr_t entry = load_elf(binary, (unsigned)length,
286	                               (uintptr_t)new_pcb->pgdir, alloc_page_helper);
287	    uintptr_t argv_va = init_user_stack(new_pcb, &argc, argv);
288	
289	    init_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp, entry,
290	                   new_pcb, argc, argv_va);
291	    list_add_tail(&new_pcb->list, &ready_queue);
292	
293	    pid_t new_pid = new_pcb->pid;
294	    disable_sum();
295	    enable_preempt();
296	    return new_pid;
297	}
