299	/* Give up every binary semaphore `task` still holds and hand each of them to
300	 * the next waiter, so that nobody stays blocked on a dead process. */
301	static void release_binsem(pcb_t *task)
302	{
303	    while (task->binsem_num > 0) {
304	        int id = task->binsem_id[--task->binsem_num];
305	        binsem_node_t *node = &binsem_nodes[id];
306	
307	        node->sem++;
308	        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
309	            list_node_t *heir_node = node->block_queue.next;
310	            pcb_t *heir = list_entry(heir_node, pcb_t, list);
311	            heir->binsem_id[heir->binsem_num++] = id;
312	            do_unblock(heir_node);
313	        }
314	    }
315	}
316	
317	/*
318	 * A task that dies while queued on a binary semaphore has already spent the
319	 * `sem--` of its pending acquire.  Give that count back, otherwise the next
320	 * release would believe somebody is still waiting and hand the lock to the
321	 * head of an empty queue.
322	 */
323	static void abandon_binsem_wait(pcb_t *task)
324	{
325	    for (int i = 0; i < BINSEM_NUMBER; i++) {
326	        binsem_node_t *node = &binsem_nodes[i];
327	        list_node_t *p;
328	        for (p = node->block_queue.next; p != &node->block_queue; p = p->next) {
329	            if (p == &task->list) {
330	                list_del(p);
331	                node->sem++;
332	                return;
333	            }
334	        }
335	    }
336	}
