409	/* the pcb of a live task with this pid, or NULL */
410	static pcb_t *find_pcb(pid_t pid)
411	{
412	    if (pid < 0) {
413	        /* -1 is the free-slot marker, never a real process */
414	        return NULL;
415	    }
416	    for (int i = 0; i < NUM_MAX_TASK; i++) {
417	        if (pcb[i].pid == pid) {
418	            return &pcb[i];
419	        }
420	    }
421	    return NULL;
422	}
