424	int do_kill(pid_t pid)
425	{
426	    disable_preempt();
427	
428	    pcb_t *victim = find_pcb(pid);
429	    int already_dying = 0;
430	    for (int i = 0; i < NR_CPUS; i++) {
431	        if (victim != NULL && pending_kill[i] == victim) {
432	            already_dying = 1;
433	        }
434	    }
435	    if (victim == NULL || already_dying ||
436	        victim->status == TASK_EXITED || victim->status == TASK_ZOMBIE) {
437	        enable_preempt();
438	        return 0;
439	    }
440	
441	    if (victim == current_running[cpu_id]) {
442	        /* killing ourselves is just an exit */
443	        enable_preempt();
444	        do_exit();
445	        return 1;
446	    }
447	
448	    if (victim->status == TASK_RUNNING) {
449	        /* It is running on the other hart: its page table is installed there
450	         * and it may still be inside a critical section, so nothing may be
451	         * taken away yet.  That hart destroys it when it next reschedules. */
452	        pending_kill[victim->cpu_id] = victim;
453	    } else {
454	        /* ready or blocked: nobody is executing it, tear it down right now */
455	        destroy_task(victim, 0);
